-- Additive: only updates the three recruiting default templates seeded in
-- 20261015090000_recruiting_templates.sql. No schema change.

UPDATE templates
SET description = 'Initial recruiter screen. Use only what was said in the conversation or notes. Never invent statements, numbers, employers or outcomes. If a topic was not discussed, write Not discussed; that is not evidence against the candidate. A claim the candidate makes without supporting detail, such as saying they are an excellent problem solver, is a self-claim, not verified evidence; label it as a self-claim. Keep contradictory statements visible instead of resolving them. If the transcript is short or unclear, say the evidence is thin. Do not score the candidate or give a hire or no-hire verdict. A section with little content can be a single line.',
    sections_json = '[{"title":"Interview Context","description":"Role, company and candidate background, only as stated in the conversation or notes."},{"title":"Key Takeaways","description":"The most important points from the conversation, stated factually."},{"title":"Evidence Against Role Requirements","description":"For each role requirement mentioned, give its status (Verified, Partially verified, Unresolved or Concern) and the supporting evidence from the conversation. If no requirements were stated, write No role requirements were provided."},{"title":"Candidate Examples and Signals","description":"Specific experience and examples the candidate gave. Label unsupported claims as self-claims."},{"title":"Logistics","description":"Availability, location, notice period and compensation expectations, only if stated."},{"title":"Concerns and Contradictions","description":"Concerns raised by the interviewer or inconsistencies in the candidate statements. If none were stated, write None stated."},{"title":"Evidence Gaps","description":"Topics that were not covered or remain unclear. Not discussed is not a negative signal."},{"title":"Suggested Follow-up","description":"Questions to ask next, based on the gaps and concerns above."},{"title":"Cautious Next Action","description":"One tentative next step for the recruiter to consider, such as another interview or a reference check. No hire or no-hire verdict and no score."}]'
WHERE id = 'default-initial-screen';

UPDATE templates
SET description = 'Technical interview. Use only what was said in the conversation or notes. Never invent statements, numbers, employers or outcomes. If a topic was not discussed, write Not discussed; that is not evidence against the candidate. A claim the candidate makes without supporting detail, such as saying they are an excellent problem solver, is a self-claim, not verified evidence; label it as a self-claim. Keep contradictory statements visible instead of resolving them. If the transcript is short or unclear, say the evidence is thin. Do not score the candidate or give a hire or no-hire verdict. A section with little content can be a single line.'
WHERE id = 'default-technical-interview';

